using System;
using System.Collections.Generic;
using System.Linq;
using ClientDataAPI;
using NUnit.Framework;

namespace ProjectLucid.Editor
{
    // Routing, lazy decoding, triggers and error propagation of the original 1.10.1 HLAutoGenerated
    // ClientDataAPI.Dispatcher, grounded in its x86-64 body. Dispatch (0x19dc5e0) compares the packet
    // type with the literal ids 0x9aa1f645 (LocalisedString), 0x8bff61d (StringTable), 0x9eb27e06
    // (SupportedLanguage) and 0x3c093300 (LocalisationDefinitions). Each arm tests its own handler field
    // before constructing a message and decodeInto-ing the caller's ref buffer, then invokes that handler;
    // an absent handler skips decoding. Every case owns its Dispatcher, messages and buffers.
    public sealed class OriginalClientDataDispatcherRoutingTests
    {
        private static NetworkBuffer Buffer(byte[] data) => new NetworkBuffer(data, 0, data.Length);

        private static LocalisedString Localised(string id, string content, int args) =>
            new LocalisedString { Id = id, Content = content, NumArgs = args };

        private static SupportedLanguage Supported(int language, int name, bool rightToLeft) =>
            new SupportedLanguage { Language = language, LocalisedName = name, IsRTL = rightToLeft };

        private static StringTable Table() =>
            new StringTable { Language = 7, Strings = new[] { Localised("table.id", "table content", 2) }, Hash = "table-hash" };

        // One dispatcher with a recording handler on every event.
        private sealed class Recorder
        {
            internal readonly Dispatcher Dispatcher = new Dispatcher();
            internal readonly List<string> Calls = new List<string>();
            internal LocalisedString Localised;
            internal StringTable Table;
            internal SupportedLanguage Supported;
            internal LocalisationDefinitions Definitions;

            internal Recorder(bool messageHandlers)
            {
                Dispatcher.OnUnknownPacket += (int type, ref NetworkBuffer buffer) => Calls.Add("unknown:" + type + "@" + buffer.Offset);
                Dispatcher.OnUnhandledPacket += (int type, ref NetworkBuffer buffer) => Calls.Add("unhandled:" + type + "@" + buffer.Offset);
                Dispatcher.OnDispatchError += (Exception error, int type, ref NetworkBuffer buffer) => Calls.Add("error:" + type + ":" + error.GetType().Name);
                if (!messageHandlers) return;
                Dispatcher.OnLocalisedString += message => { Calls.Add("localised"); Localised = message; };
                Dispatcher.OnStringTable += message => { Calls.Add("table"); Table = message; };
                Dispatcher.OnSupportedLanguage += message => { Calls.Add("supported"); Supported = message; };
                Dispatcher.OnLocalisationDefinitions += message => { Calls.Add("definitions"); Definitions = message; };
            }
        }

        // The restored ID constants equal the literals compared at 0x19dc637..0x19dc714.
        [Test]
        public void PacketIdsEqualTheOriginalDispatchLiterals()
        {
            Assert.That(LocalisedString.ID, Is.EqualTo(unchecked((int)0x9aa1f645)));
            Assert.That(StringTable.ID, Is.EqualTo(0x8bff61d));
            Assert.That(SupportedLanguage.ID, Is.EqualTo(unchecked((int)0x9eb27e06)));
            Assert.That(LocalisationDefinitions.ID, Is.EqualTo(0x3c093300));
        }

        // Each literal id reaches only its own handler with the decoded payload, and the decode consumes
        // the caller's ref buffer. Catches a missing or swapped route (the SupportedLanguage deletion that
        // the original three cases missed) and a wrong or skipped decoder.
        [Test]
        public void EachLiteralIdReachesOnlyItsHandlerWithTheDecodedPayload()
        {
            byte[] localised = Localised("route.id", "route content", 3).encode();
            var recorder = new Recorder(true);
            NetworkBuffer buffer = Buffer(localised);
            recorder.Dispatcher.Dispatch(LocalisedString.ID, ref buffer);
            Assert.That(recorder.Calls, Is.EqualTo(new[] { "localised" }));
            Assert.That(new[] { recorder.Localised.Id, recorder.Localised.Content }, Is.EqualTo(new[] { "route.id", "route content" }));
            Assert.That(recorder.Localised.NumArgs, Is.EqualTo(3));
            Assert.That(buffer.Offset, Is.EqualTo(localised.Length), "decodeInto consumed the caller's buffer");

            byte[] table = Table().encode();
            recorder = new Recorder(true);
            buffer = Buffer(table);
            recorder.Dispatcher.Dispatch(StringTable.ID, ref buffer);
            Assert.That(recorder.Calls, Is.EqualTo(new[] { "table" }));
            Assert.That(recorder.Table.Language, Is.EqualTo(7));
            Assert.That(recorder.Table.Hash, Is.EqualTo("table-hash"));
            Assert.That(recorder.Table.Strings.Select(entry => entry.Id + "=" + entry.Content + "/" + entry.NumArgs), Is.EqualTo(new[] { "table.id=table content/2" }));
            Assert.That(buffer.Offset, Is.EqualTo(table.Length));

            byte[] supported = Supported(11, 22, true).encode();
            recorder = new Recorder(true);
            buffer = Buffer(supported);
            recorder.Dispatcher.Dispatch(SupportedLanguage.ID, ref buffer);
            Assert.That(recorder.Calls, Is.EqualTo(new[] { "supported" }));
            Assert.That(new[] { recorder.Supported.Language, recorder.Supported.LocalisedName }, Is.EqualTo(new[] { 11, 22 }));
            Assert.That(recorder.Supported.IsRTL, Is.True);
            Assert.That(buffer.Offset, Is.EqualTo(supported.Length));

            byte[] definitions = new LocalisationDefinitions { SupportedLanguages = new[] { Supported(33, 44, false) }, StringTable = Table() }.encode();
            recorder = new Recorder(true);
            buffer = Buffer(definitions);
            recorder.Dispatcher.Dispatch(LocalisationDefinitions.ID, ref buffer);
            Assert.That(recorder.Calls, Is.EqualTo(new[] { "definitions" }));
            Assert.That(recorder.Definitions.SupportedLanguages.Select(language => language.Language + "/" + language.LocalisedName), Is.EqualTo(new[] { "33/44" }));
            Assert.That(recorder.Definitions.StringTable.Hash, Is.EqualTo("table-hash"));
            Assert.That(buffer.Offset, Is.EqualTo(definitions.Length));
        }

        // With no handler for a known id, the arm jumps away before constructing or decoding a message:
        // the payload reaches OnUnhandledPacket undecoded (cursor still 0), never OnUnknownPacket.
        // Catches eager decoding and known ids falling into the unknown arm.
        [Test]
        public void KnownIdsWithoutAHandlerReachUnhandledUndecoded()
        {
            byte[] payload = Localised("lazy.id", "lazy content", 1).encode();
            foreach (int id in new[] { LocalisedString.ID, StringTable.ID, SupportedLanguage.ID, LocalisationDefinitions.ID })
            {
                var recorder = new Recorder(false);
                NetworkBuffer buffer = Buffer(payload);
                recorder.Dispatcher.Dispatch(id, ref buffer);
                Assert.That(recorder.Calls, Is.EqualTo(new[] { "unhandled:" + id + "@0" }), "id " + id);
                Assert.That(buffer.Offset, Is.Zero);
                Assert.That(LocalisedString.decode(ref buffer).Content, Is.EqualTo("lazy content"), "the raw payload is intact");
            }
        }

        // Each trigger (0x19dc520, 0x19dc550, 0x19dc580, 0x19dc5b0) reads only its own handler field,
        // invokes it with the same reference and returns whether it was non-null. Catches a missing or
        // crossed trigger and a copied argument.
        [Test]
        public void EachTriggerInvokesOnlyItsHandlerWithTheSameReference()
        {
            var recorder = new Recorder(false);
            var localised = Localised("trigger.id", "trigger content", 0);
            var table = Table();
            var supported = Supported(1, 2, false);
            var definitions = new LocalisationDefinitions();
            Assert.That(recorder.Dispatcher.TriggerOnLocalisedString(localised), Is.False);
            Assert.That(recorder.Dispatcher.TriggerOnStringTable(table), Is.False);
            Assert.That(recorder.Dispatcher.TriggerOnSupportedLanguage(supported), Is.False);
            Assert.That(recorder.Dispatcher.TriggerOnLocalisationDefinitions(definitions), Is.False);
            Assert.That(recorder.Calls, Is.Empty);

            recorder = new Recorder(true);
            Assert.That(recorder.Dispatcher.TriggerOnLocalisedString(localised), Is.True);
            Assert.That(recorder.Dispatcher.TriggerOnStringTable(table), Is.True);
            Assert.That(recorder.Dispatcher.TriggerOnSupportedLanguage(supported), Is.True);
            Assert.That(recorder.Dispatcher.TriggerOnLocalisationDefinitions(definitions), Is.True);
            Assert.That(recorder.Calls, Is.EqualTo(new[] { "localised", "table", "supported", "definitions" }));
            Assert.That(recorder.Localised, Is.SameAs(localised));
            Assert.That(recorder.Table, Is.SameAs(table));
            Assert.That(recorder.Supported, Is.SameAs(supported));
            Assert.That(recorder.Definitions, Is.SameAs(definitions));
        }

        // Dispatch catches any exception from decoding or a handler and passes the same exception, the
        // packet type and the caller's ref buffer to OnDispatchError. A handler failure arrives after the
        // decode advanced the cursor; a malformed payload (descending tag) fails inside decodeInto before
        // the handler runs; a replacement buffer assigned by the error handler reaches the caller.
        [Test]
        public void DecodeAndHandlerFailuresReachTheErrorHandlerWithTheCallersBuffer()
        {
            var failure = new InvalidOperationException("handler failure");
            byte[] payload = Supported(5, 6, false).encode();
            var dispatcher = new Dispatcher();
            dispatcher.OnSupportedLanguage += message => throw failure;
            Exception reported = null;
            int reportedType = 0, reportedOffset = -1;
            byte[] replacement = { 9, 9 };
            dispatcher.OnDispatchError += (Exception error, int type, ref NetworkBuffer buffer) =>
            {
                reported = error;
                reportedType = type;
                reportedOffset = buffer.Offset;
                buffer = Buffer(replacement);
            };
            NetworkBuffer caller = Buffer(payload);
            dispatcher.Dispatch(SupportedLanguage.ID, ref caller);
            Assert.That(reported, Is.SameAs(failure));
            Assert.That(reportedType, Is.EqualTo(SupportedLanguage.ID));
            Assert.That(reportedOffset, Is.EqualTo(payload.Length), "the error handler sees the decoded cursor");
            Assert.That(caller.Remaining, Is.EqualTo(replacement.Length), "the error handler's ref assignment reaches the caller");

            // Tag 2 with a one-character string, then tag 1: decodeInto rejects the descending tag.
            byte[] malformed = { 2, 2, (byte)'a', 1 };
            var recorder = new Recorder(true);
            NetworkBuffer bad = Buffer(malformed);
            recorder.Dispatcher.Dispatch(LocalisedString.ID, ref bad);
            Assert.That(recorder.Calls, Is.EqualTo(new[] { "error:" + LocalisedString.ID + ":IndexOutOfRangeException" }), "the handler never runs");
        }

        // OnUnhandledPacket and OnUnknownPacket receive the caller's buffer by ref.
        [Test]
        public void UnhandledAndUnknownHandlersShareTheCallersRefBuffer()
        {
            byte[] replacement = { 1, 2, 3 };
            foreach (bool unknown in new[] { false, true })
            {
                var dispatcher = new Dispatcher();
                if (unknown) dispatcher.OnUnknownPacket += (int type, ref NetworkBuffer buffer) => buffer = Buffer(replacement);
                else dispatcher.OnUnhandledPacket += (int type, ref NetworkBuffer buffer) => buffer = Buffer(replacement);
                NetworkBuffer caller = Buffer(new byte[0]);
                dispatcher.Dispatch(unknown ? 12345 : StringTable.ID, ref caller);
                Assert.That(caller.Remaining, Is.EqualTo(replacement.Length), unknown ? "unknown" : "unhandled");
            }
        }
    }
}
